/**
 * Assets deliberately left out of the distribution, keyed by asset status.
 */
export type ConfidenceSummaryExcludedByAssetStatus = { [key: string]: number };

export interface ConfidenceSummary {
  /** Stated in the payload so a report built from it can quote the basis rather than guess it. One point per asset, not per observation — weighting by scan frequency would describe our scheduling, not our evidence quality. */
  basis: ConfidenceSummaryBasis;
  scored: number;
  /** Active assets with no observation at all. Non-zero means a data problem, and hiding it would be the wrong default. */
  unscored: number;
  /** Assets deliberately left out of the distribution, keyed by asset status. */
  excludedByAssetStatus: ConfidenceSummaryExcludedByAssetStatus;
  distinctValues: number;
  min: number | null;
  max: number | null;
  mean: number | null;
  buckets: ConfidenceBucketCount[];
}

/**
 * D3 — what has been examined, and what has never been looked at. The denominator is surfaces, not assets: how much cryptography hides in a surface nobody examined is unknowable from this data, so `examinedSurfaces / totalSurfaces` must not be presented as a percentage of the estate.
 */
export interface ProjectCoverage {
  projectId: number;
  generatedAt: string;
  examinedSurfaces: number;
  totalSurfaces: number;
  /** Every catalogue surface with any run or asset. A surface absent from this list has never been examined at all — that absence is the machine-readable half of the answer. */
  surfaces: SurfaceCoverage[];
  confidence: ConfidenceSummary;
}

export interface CycloneDxProperty {
  name: string;
  value?: string;
}

export interface CycloneDxOccurrence {
  location: string;
  line?: number;
  symbol?: string;
}

export type CycloneDxCryptoPropertiesAssetType =
  (typeof CycloneDxCryptoPropertiesAssetType)[keyof typeof CycloneDxCryptoPropertiesAssetType];

export const CycloneDxCryptoPropertiesAssetType = {
  algorithm: "algorithm",
  certificate: "certificate",
  protocol: "protocol",
  "related-crypto-material": "related-crypto-material",
} as const;

export type CycloneDxCryptoPropertiesAlgorithmProperties = {
  primitive?: string;
  algorithmFamily?: string;
  /** Key or parameter size as a string. Present only when the inventory actually determined it — never a guessed default (G-05). */
  parameterSetIdentifier?: string;
  ellipticCurve?: string;
  mode?: string;
  padding?: string;
  cryptoFunctions?: string[];
};

export type CycloneDxCryptoPropertiesRelatedCryptoMaterialProperties = {
  type?: string;
  id?: string;
  state?: string;
  /** Size in bits. Present only when determined. */
  size?: number;
};

export type CycloneDxCryptoPropertiesCertificateProperties = {
  subjectName?: string;
  issuerName?: string;
  serialNumber?: string;
  notValidBefore?: string;
  notValidAfter?: string;
};

export type CycloneDxCryptoPropertiesProtocolProperties = {
  type?: string;
  version?: string;
};

export interface CycloneDxCryptoProperties {
  assetType: CycloneDxCryptoPropertiesAssetType;
  algorithmProperties?: CycloneDxCryptoPropertiesAlgorithmProperties;
  relatedCryptoMaterialProperties?: CycloneDxCryptoPropertiesRelatedCryptoMaterialProperties;
  certificateProperties?: CycloneDxCryptoPropertiesCertificateProperties;
  protocolProperties?: CycloneDxCryptoPropertiesProtocolProperties;
  oid?: string;
}

export type CycloneDxComponentEvidence = {
  occurrences?: CycloneDxOccurrence[];
};

export interface CycloneDxComponent {
  type: string;
  "bom-ref": string;
  name: string;
  version?: string;
  description?: string;
  cryptoProperties?: CycloneDxCryptoProperties;
  evidence?: CycloneDxComponentEvidence;
  properties?: CycloneDxProperty[];
}

export interface CycloneDxDependency {
  ref: string;
  dependsOn?: string[];
  provides?: string[];
}

/**
 * Assets breaching Mosca at this instant, one count per Q-Day scenario.
 */
export interface TimelineScenarioCounts {
  [key: string]: number;
}

export interface TimelinePointBase {
  /** For an observed point this is a real collection_runs timestamp, not a grid tick. */
  at: string;
  assetsKnown: number;
  /** Assets present and not yet gone at this instant. The number the verdicts are over. */
  assetsPresent: number;
  pqcAssets: number;
  hygieneAssets: number;
  unmappedAssets: number;
  breachedByScenario: TimelineScenarioCounts;
}

export type ObservedPointKind =
  (typeof ObservedPointKind)[keyof typeof ObservedPointKind];

export const ObservedPointKind = {
  observed: "observed",
} as const;

export type ObservedPoint = TimelinePointBase & {
  kind: ObservedPointKind;
  collectionRunIds: number[];
  surfaces: string[];
  assetsAdded: number;
};

export type ProjectedPointKind =
  (typeof ProjectedPointKind)[keyof typeof ProjectedPointKind];

export const ProjectedPointKind = {
  projected: "projected",
} as const;

export type ProjectedPoint = TimelinePointBase & {
  kind: ProjectedPointKind;
  year: number;
};

export interface ObservedHistory {
  /** False when fewer than two distinct collection instants exist. The client must draw no line. */
  sufficientForTrend: boolean;
  reason: string;
  distinctCollectionInstants: number;
  observedSpanDays: number | null;
  firstObservedAt: string | null;
  lastObservedAt: string | null;
  completedRuns: number;
  /** A failed run places no point on the axis; it is reported here instead. */
  failedRuns: number;
  points: ObservedPoint[];
}

export interface ProjectedHorizon {
  /** What is held constant. Projections move because Z shrinks, not because the estate changed. */
  assumption: string;
  basisAt: string;
  points: ProjectedPoint[];
}

export interface DeadlineMarker {
  /** Keyed on framework + type + effective date + appliesTo + securityStrength. */
  id: string;
  type: string;
  label: string;
  effect: string;
  effectiveFrom: string;
  year: number;
  inEffect: boolean;
  appliesTo: string | null;
  securityStrength: string | null;
  framework: string;
  frameworkName: string | null;
  requirement: string;
  citation: Citation;
  confidence: string;
  draftStatus: string | null;
  algorithms: string[];
  assets: number;
  caveats: string[];
}

export type EstateRollupProjectsItem = {
  id: number;
  name: string;
  assets: number;
  presentAssets: number;
};

export interface EstateRollup {
  projects: EstateRollupProjectsItem[];
  /** Assets whose location carries no project prefix. Surfaces such as tls/certificate have no project. */
  unassociatedAssets: number;
  totalAssets: number;
  presentAssets: number;
}

export type PostureTimelineInputsSecrecyLifetimeBySource = {
  [key: string]: number;
};

export type PostureTimelineInputsSecrecyLifetime = {
  bySource: PostureTimelineInputsSecrecyLifetimeBySource;
  assumedForAssets: number;
  bases: string[];
};

export type PostureTimelineInputsMigrationYears = {
  defaultValue: number;
  assetsWithRecordedEffort: number;
  /** States plainly that Y is not measured yet, so a reader knows X vs Z decided the verdict. */
  basis: string;
};

export interface PostureTimelineInputs {
  secrecyLifetime: PostureTimelineInputsSecrecyLifetime;
  migrationYears: PostureTimelineInputsMigrationYears;
}

export type PostureTimelineScenariosItem = {
  name: string;
  qDayYear: number;
  rationale: string;
  confidence: string;
};

export type PostureTimelineNotCollectedItem = {
  id: string;
  label: string;
  reason: string;
};

export interface PostureTimeline {
  generatedAt: string;
  now: string;
  /** Mandatory wherever a scenario year is shown — a Q-Day year is a scenario, not a forecast. */
  framing: string;
  scenarios: PostureTimelineScenariosItem[];
  estate: EstateRollup;
  observed: ObservedHistory;
  projected: ProjectedHorizon;
  deadlines: DeadlineMarker[];
  inputs: PostureTimelineInputs;
  /** Facts a reader expects on a time-pressure panel that this product cannot produce, stated rather than omitted. */
  notCollected: PostureTimelineNotCollectedItem[];
}

export type CbomDocumentBomFormat =
  (typeof CbomDocumentBomFormat)[keyof typeof CbomDocumentBomFormat];

export const CbomDocumentBomFormat = {
  CycloneDX: "CycloneDX",
} as const;

export type CbomDocumentSpecVersion =
  (typeof CbomDocumentSpecVersion)[keyof typeof CbomDocumentSpecVersion];

export const CbomDocumentSpecVersion = {
  "17": "1.7",
} as const;

export type CbomDocumentMetadataTools = {
  components: CycloneDxComponent[];
};

export type CbomDocumentMetadata = {
  timestamp: string;
  tools: CbomDocumentMetadataTools;
  properties?: CycloneDxProperty[];
};

/**
 * A CycloneDX 1.7 CBOM. Schema conformance is proven against the vendored official schema in `@workspace/cbom`'s own suite; this documents the subset the builder emits and is not a substitute for that validation.
 */
export interface CbomDocument {
  bomFormat: CbomDocumentBomFormat;
  specVersion: CbomDocumentSpecVersion;
  serialNumber?: string;
  version: number;
  metadata: CbomDocumentMetadata;
  components: CycloneDxComponent[];
  dependencies: CycloneDxDependency[];
}

